function render(){if(!state.image)return;const view=state.view;let mask=state.editMask||state.result?.mask;if(mask&&!state.editMask&&!$('show-inference').checked)mask=mask.map((v,i)=>state.result.inferredMask[i]?0:v);ctx.clearRect(0,0,state.width,state.height);if(view==='terrain'){drawTerrain();drawInteraction();return;}if(view==='surface'&&state.result?.surfaceCue){drawDepth(ctx,state.result.surfaceCue);drawInteraction();return;}if(view==='depth'&&state.result?.depth){drawDepth(ctx);drawInteraction();return;}if(view==='skeleton'){ctx.fillStyle='#102a24';ctx.fillRect(0,0,state.width,state.height);}else if(view==='mask'&&mask){const gray=Uint8Array.from(mask,x=>x?255:0);ctx.drawImage(createRaster(gray,'gray'),0,0);}else if(view==='enhanced'&&state.result?.enhanced){enhancedCanvas??=createRaster(state.result.enhanced,'gray');ctx.drawImage(enhancedCanvas,0,0);}else{ctx.drawImage(source,0,0);if(view==='overlay'&&mask&&(state.editMask||$('show-mask').checked)){const raster=state.editMask?createRaster(mask.map((v,i)=>v!==state.result.mask[i]?1:0),state.tool==='erase'?'erase':'mask'):(maskCanvas??=createRaster(mask,'mask'));ctx.drawImage(raster,0,0);}}if((view==='overlay'||view==='skeleton')&&!state.editMask)drawPaths(ctx,1,1,$('show-nodes').checked);drawInteraction();}
function scheduleRender(){if(renderFrame)return;renderFrame=requestAnimationFrame(()=>{renderFrame=0;render();});}
function drawInteraction(){ictx.clearRect(0,0,state.width,state.height);if(!state.roi||state.view==='terrain')return;const r=state.stroke?.type==='crop'?state.stroke.roi:state.roi;ictx.save();const screenScale=state.width/(wrap.clientWidth||state.width);if(state.tool==='crop'){ictx.fillStyle='rgba(10,23,20,.38)';ictx.beginPath();ictx.rect(0,0,state.width,state.height);ictx.rect(r.x+r.width,r.y,-r.width,r.height);ictx.fill('evenodd');ictx.strokeStyle='#b3f5cf';ictx.lineWidth=screenScale;ictx.setLineDash([5*screenScale,4*screenScale]);ictx.strokeRect(r.x,r.y,r.width,r.height);ictx.setLineDash([]);ictx.fillStyle='#d1ffe5';for(const [x,y] of [[r.x,r.y],[r.x+r.width,r.y],[r.x,r.y+r.height],[r.x+r.width,r.y+r.height]])ictx.fillRect(x-2.5*screenScale,y-2.5*screenScale,5*screenScale,5*screenScale);}if(state.pointer&&state.tool!=='crop'){ictx.beginPath();ictx.arc(state.pointer.x,state.pointer.y,+$('brush-size').value/2,0,Math.PI*2);ictx.strokeStyle=state.tool==='erase'?'#ffbaae':'#c4ffe3';ictx.lineWidth=1.4*screenScale;ictx.stroke();}ictx.restore();}
function stopWorker(){state.job++;state.worker?.terminate();state.worker=null;if(pendingReject){pendingReject(new DOMException(t('已取消'),'AbortError'));pendingReject=null;}state.busy=false;$('busy-overlay').hidden=true;updateUI();}
function runTask(kind,mask,context){stopWorker();state.taskKind=kind;state.busy=true;state.stroke=null;const id=++state.job;$('busy-label').textContent=kind==='extract'?t('正在识别凹槽、连接通道并提取中心线…'):t('正在更新路径连接…');$('busy-overlay').hidden=false;updateUI();return new Promise((resolve,reject)=>{pendingReject=reject;const worker=new Worker('./worker.js',{type:'module'});state.worker=worker;const done=()=>{worker.terminate();state.worker=null;pendingReject=null;state.busy=false;$('busy-overlay').hidden=true;updateUI();};worker.onmessage=({data})=>{if(data.id!==state.job)return;done();if(data.error)reject(new Error(data.error));else{state.elapsed=data.elapsed;resolve(data.result);}};worker.onerror=e=>{done();reject(new Error(e.message||t('图像处理失败，请刷新页面重试')));};worker.postMessage({id,kind,width:state.width,height:state.height,rgba:kind==='extract'?state.rgba:undefined,roi:{...state.roi},options:options(),mask,inferredMask:context?.inferredMask??state.result?.inferredMask,bridges:context?.bridges??state.result?.bridges});});}
async function extract(){if(!state.image||state.busy)return;const usedOptions=options();try{const result=await runTask('extract');state.result=result;state.resultOptions=usedOptions;state.dirty=false;state.undo=[];state.redo=[];state.corrections=0;state.editMask=null;invalidateCaches();setStep('correct',false);state.tool='brush';setTool('brush');updateUI();render();if(!result.stats.area)toast(t('未找到通道。请提高识别强度，或重新选择区域'));else if(!displayGraph(result).edges.length)toast(t('只检测到细碎区域，可切换“完整骨架”检查，或调整识别区域'));else if(result.stats.coverage>.65)toast(t('选中区域较多，可能包含土壤。建议降低识别强度'));else toast(t('已完成提取，请检查连接并校正'));return result;}catch(e){if(e.name!=='AbortError')toast(t(e.message));return null;}}
function snapshot(){return {mask:state.result.mask.slice(),inferredMask:state.result.inferredMask.slice(),bridges:state.result.bridges,corrections:state.corrections};}
async function applyMask(mask,action='edit',historyItem=null){if(!state.result)return;const before=snapshot(),priorResult=state.result;try{const result=await runTask('analyze',mask,historyItem);state.result={...priorResult,...result};state.editMask=null;if(action==='edit'){state.undo.push(before);state.redo=[];state.corrections++;}else if(action==='undo'){state.undo.pop();state.redo.push(before);state.corrections=historyItem.corrections;}else if(action==='redo'){state.redo.pop();state.undo.push(before);state.corrections=historyItem.corrections;}if(state.undo.length>15)state.undo.shift();invalidateCaches();updateUI();render();}catch(e){state.editMask=null;render();if(e.name!=='AbortError')toast(t(e.message));}}
function undo(){if(state.busy||!state.undo.length)return;const s=state.undo.at(-1);return applyMask(s.mask,'undo',s);}function redo(){if(state.busy||!state.redo.length)return;const s=state.redo.at(-1);return applyMask(s.mask,'redo',s);}
function changeROI(roi){if(state.busy)return;state.roi=validateROI(roi,state.width,state.height);state.result=null;state.resultOptions=null;state.undo=[];state.redo=[];state.corrections=0;state.dirty=false;state.editMask=null;invalidateCaches();setView('original');setStep('region',false);setTool('crop');updateUI();render();}
async function loadImage(url,name,isSample=false){const token=++state.load;stopWorker();state.editMask=null;state.stroke=null;const image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error(t('无法读取这张图片，请使用 JPG、PNG 或 WebP')));image.src=url;});if(token!==state.load)return;if(image.naturalWidth*image.naturalHeight>60000000)throw new Error(t('图片超过 6000 万像素，请缩小后重试'));state.image=image;state.name=name;state.isSample=isSample;state.originalWidth=image.naturalWidth;state.originalHeight=image.naturalHeight;const ratio=Math.min(1,1400/Math.max(image.naturalWidth,image.naturalHeight));state.width=Math.max(1,Math.round(image.naturalWidth*ratio));state.height=Math.max(1,Math.round(image.naturalHeight*ratio));source.width=canvas.width=interaction.width=state.width;source.height=canvas.height=interaction.height=state.height;sctx.fillStyle='#fff';sctx.fillRect(0,0,state.width,state.height);sctx.drawImage(image,0,0,state.width,state.height);state.rgba=sctx.getImageData(0,0,state.width,state.height).data;state.zoom=1;state.panX=state.panY=0;state.terrainAngle=-.15;$('path-mode').value='main';$('show-mask').checked=false;$('show-nodes').checked=false;const suggested=suggestROI(state.rgba,state.width,state.height);changeROI(suggested.roi);fitCanvas();if(isSample)await extract();else toast(suggested.found?t('已建议识别区域，请检查地表入口后开始提取'):t('已载入图片，请框选需要识别的区域'));}catch(e){if(token===state.load)toast(t(e.message));}finally{if(url.startsWith('blob:'))URL.revokeObjectURL(url);}}
function loadFile(file){if(!file)return;if(!/^image\/(png|jpeg|webp|bmp)$/.test(file.type)&&! /\.(png|jpe?g|webp|bmp)$/i.test(file.name)){toast(t('请选择 JPG、PNG、WebP 或 BMP 图片'));return;}if(file.size>25*1024*1024){toast(t('图片超过 25 MB，请压缩后再上传'));return;}return loadImage(URL.createObjectURL(file),file.name);}
function point(e){const r=interaction.getBoundingClientRect();return {x:Math.max(0,Math.min(state.width-.001,(e.clientX-r.left)*state.width/r.width)),y:Math.max(0,Math.min(state.height-.001,(e.clientY-r.top)*state.height/r.height))};}
function paint(from,to){if(!state.editMask)return;const r=+$('brush-size').value/2,steps=Math.max(1,Math.ceil(Math.hypot(to.x-from.x,to.y-from.y)/Math.max(1,r/3))),roi=state.roi;for(let j=0;j<=steps;j++){const cx=from.x+(to.x-from.x)*j/steps,cy=from.y+(to.y-from.y)*j/steps;for(let y=Math.max(roi.y,Math.floor(cy-r));y<Math.min(roi.y+roi.height,Math.ceil(cy+r));y++)for(let x=Math.max(roi.x,Math.floor(cx-r));x<Math.min(roi.x+roi.width,Math.ceil(cx+r));x++)if((x+.5-cx)**2+(y+.5-cy)**2<=r*r)state.editMask[y*state.width+x]=state.tool==='brush'?1:0;}}
let space=false;
interaction.addEventListener('pointerdown',e=>{if(state.busy||!state.image||e.button!==0)return;interaction.setPointerCapture(e.pointerId);const p=point(e);state.pointer=p;if(state.view==='terrain'){state.stroke={type:'orbit',x:e.clientX,angle:state.terrainAngle};return;}if(space){state.stroke={type:'pan',x:e.clientX,y:e.clientY,panX:state.panX,panY:state.panY};return;}if(state.tool==='crop'){state.stroke={type:'crop',start:p,roi:{x:p.x,y:p.y,width:1,height:1}};}else if(state.result){state.editMask=state.result.mask.slice();state.stroke={type:'paint',last:p};paint(p,p);scheduleRender();}e.preventDefault();});
interaction.addEventListener('pointermove',e=>{state.pointer=point(e);const stroke=state.stroke;if(stroke?.type==='orbit'){state.terrainAngle=stroke.angle+(e.clientX-stroke.x)/150;scheduleRender();return;}if(stroke?.type==='pan'){state.panX=stroke.panX+e.clientX-stroke.x;state.panY=stroke.panY+e.clientY-stroke.y;fitCanvas();return;}if(stroke?.type==='crop'){const p=state.pointer,s=stroke.start;stroke.roi={x:Math.floor(Math.min(p.x,s.x)),y:Math.floor(Math.min(p.y,s.y)),width:Math.max(1,Math.ceil(Math.abs(p.x-s.x))),height:Math.max(1,Math.ceil(Math.abs(p.y-s.y)))};}else if(stroke?.type==='paint'){paint(stroke.last,state.pointer);stroke.last=state.pointer;scheduleRender();}drawInteraction();});
interaction.addEventListener('pointerup',()=>{const stroke=state.stroke;state.stroke=null;if(stroke?.type==='crop'){if(stroke.roi.width>=5&&stroke.roi.height>=5){changeROI(stroke.roi);toast(t('识别区域已更新，点击提取路径'));}else drawInteraction();}else if(stroke?.type==='paint'){const mask=state.editMask;if(!mask.some((v,i)=>v!==state.result.mask[i])){state.editMask=null;render();return;}applyMask(mask);} });
interaction.addEventListener('pointercancel',()=>{state.stroke=null;state.editMask=null;render();});interaction.addEventListener('pointerleave',()=>{if(!state.stroke){state.pointer=null;drawInteraction();}});
function download(blob,extension,label){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=state.name.replace(/\.[^.]+$/,'')+'-'+label+'.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(t('已导出 {name}',{name:a.download}));}
function exportSource(includeInference=true){
 if(!state.result)throw new Error(t('请先提取路径'));if(includeInference)return state.result;
 const mask=state.result.mask.map((v,i)=>state.result.inferredMask[i]?0:v);
 const r=analyzeMask(mask,state.width,state.height,state.roi);const direct={...state.result,...r,inferredMask:new Uint8Array(mask.length),bridges:[]};direct.centerGraph=centerRoutes(direct,state.width,state.height);return direct;
}
function exportData(includeInference=true){
 const result=exportSource(includeInference);
 return serializeNetwork(result,displayGraph(result),{width:state.width,height:state.height,originalWidth:state.originalWidth,originalHeight:state.originalHeight,name:state.name,roi:state.roi,parameters:state.resultOptions,manualEdits:state.corrections},includeInference);
}
async function exportResult(kind){
 if(!state.result||state.busy)return;const include=$('export-inferred').checked,result=exportSource(include),graph=exportData(include);
 if(kind==='json'){download(new Blob([JSON.stringify(graph,null,2)],{type:'application/json'}),'json','network');return;}
 if(kind==='svg'){
  const sx=state.originalWidth/state.width,sy=state.originalHeight/state.height;const paths=[];
  for(const edge of displayGraph(result).edges){let run=[],lastKind=null;const flush=()=>{if(run.length<2)return;paths.push(`<path data-edge="${edge.id}" data-provenance="${lastKind?'inferred':'direct-or-manually-edited'}" stroke="${lastKind?'#bd7b26':'#157858'}" ${lastKind?'stroke-dasharray="4 3"':''} d="${run.map((p,i)=>(i?'L':'M')+(p[0]*sx).toFixed(3)+' '+(p[1]*sy).toFixed(3)).join(' ')}"/>`);};for(let i=1;i<edge.points.length;i++){const a=edge.points[i-1],b=edge.points[i],type=edge.inferredSegments[i-1];if(type!==lastKind){flush();run=[a];lastKind=type;}run.push(b);}flush();}
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${state.originalWidth} ${state.originalHeight}" width="${state.originalWidth}" height="${state.originalHeight}"><title>Ant paths; orange dashed segments are inferred</title><g fill="none" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths.join('')}</g></svg>`;download(new Blob([svg],{type:'image/svg+xml'}),'svg','paths');return;
 }
 const c=document.createElement('canvas');c.width=state.originalWidth;c.height=state.originalHeight;if(c.width*c.height>24000000){toast(t('原图过大，PNG 导出限制为 2400 万像素；可导出 SVG 或 JSON'));return;}const cx=c.getContext('2d');
 if(kind==='mask'||kind==='depth'){const data=kind==='depth'?Uint8Array.from(result.depth,x=>Math.round(x*255)):Uint8Array.from(result.mask,x=>x?255:0),m=createRaster(data,'gray');cx.imageSmoothingEnabled=kind==='depth';cx.drawImage(m,0,0,c.width,c.height);}else if(kind==='centerline'){drawPaths(cx,c.width/state.width,c.height/state.height,false,result,include,true);}else{cx.drawImage(state.image,0,0,c.width,c.height);if($('show-mask').checked)cx.drawImage(createRaster(result.mask,'mask'),0,0,c.width,c.height);drawPaths(cx,c.width/state.width,c.height/state.height,$('show-nodes').checked,result,include);}
 c.toBlob(blob=>{if(blob)download(blob,'png',kind==='depth'?'relative-depression':kind);else toast(t('导出失败，请尝试较小图片'));},'image/png');
}
for(const id of ['upload-button','replace-image-button'])$(id).onclick=()=>$('file-input').click();$('path-smoothing').oninput=()=>{syncSliders();scheduleRender();};$('path-mode').onchange=()=>{render();toast($('path-mode').value==='main'?t('已保留主要中心线，导出同步生效'):t('已显示完整骨架，可对比被简化的分支'));};$('file-input').onchange=e=>{loadFile(e.target.files[0]);e.target.value='';};$('sample-button').onclick=()=>loadImage('./assets/sample.jpg','蚁穴示例.jpg',true);$('extract-button').onclick=extract;$('auto-region').onclick=()=>{const s=suggestROI(state.rgba,state.width,state.height);changeROI(s.roi);toast(s.found?t('已建议土壤区域，请检查地表入口'):t('没有找到清晰地表，请手动框选'));};$('reset-region').onclick=()=>changeROI({x:0,y:0,width:state.width,height:state.height});$('reset-params').onclick=()=>{if(state.busy)return;for(const [id,v]of Object.entries(defaults))$(id).value=v;$('close-gaps').checked=false;$('reconstruct-gaps').checked=true;$('detect-surface').checked=true;state.dirty=!!state.result;syncSliders();updateUI();};for(const id of [...Object.keys(defaults),'close-gaps','reconstruct-gaps','detect-surface'])$(id).addEventListener('input',()=>{state.dirty=!!state.result;syncSliders();updateUI();});$('brush-size').oninput=()=>{syncSliders();updateUI();drawInteraction();};$('show-nodes').onchange=render;$('show-mask').onchange=render;$('show-inference').onchange=()=>{maskCanvas=null;render();};interaction.addEventListener('dblclick',()=>{if(state.view==='terrain'){state.terrainAngle=-.15;render();}});$$('[data-step]').forEach(b=>b.onclick=()=>setStep(b.dataset.step));$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));['crop','brush','erase'].forEach(t=>$(t+'-tool').onclick=()=>setTool(t));$('undo-button').onclick=undo;$('redo-button').onclick=redo;$('export-button').onclick=()=>{setStep('export');if(innerWidth<690)$('export-section').scrollIntoView({behavior:'smooth',block:'center'});};$$('[data-export]').forEach(b=>b.onclick=()=>exportResult(b.dataset.export));$('zoom-in').onclick=()=>{state.zoom=Math.min(8,state.zoom*1.25);fitCanvas();};$('zoom-out').onclick=()=>{state.zoom=Math.max(.5,state.zoom/1.25);fitCanvas();};$('fit-button').onclick=()=>{state.zoom=1;state.panX=state.panY=0;fitCanvas();};$('cancel-button').onclick=()=>{stopWorker();state.editMask=null;state.stroke=null;render();toast(t('已取消，保留上一次完成的结果'));};$('help-button').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();$('help-dialog').onclick=e=>{if(e.target===$('help-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
new ResizeObserver(fitCanvas).observe(stage);
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('help-dialog').open)return;if(e.code==='Space'&&stage.contains(document.activeElement)){space=true;e.preventDefault();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();}else if(!e.ctrlKey&&!e.metaKey&&!state.busy){if(e.key.toLowerCase()==='r')setTool('crop');if(e.key.toLowerCase()==='b')setTool('brush');if(e.key.toLowerCase()==='e')setTool('erase');}});window.addEventListener('keyup',e=>{if(e.code==='Space')space=false;});window.addEventListener('blur',()=>space=false);interaction.addEventListener('pointerdown',()=>stage.focus({preventScroll:true}));
for(const type of ['dragenter','dragover','dragleave','drop'])window.addEventListener(type,e=>{e.preventDefault();if(type==='dragenter'){dragDepth++;stage.classList.add('dragging');}if(type==='dragleave'){dragDepth--;if(dragDepth<=0)stage.classList.remove('dragging');}if(type==='drop'){dragDepth=0;stage.classList.remove('dragging');loadFile(e.dataTransfer.files[0]);}});
// Embedding API: shares exactly the same state and actions as the visible controls.
window.Formic={version:ENGINE_VERSION,getLanguage,setLanguage,getResult:(includeInference=true)=>state.result?exportData(includeInference):null,extract:()=>extract(),loadFile,setROI:roi=>{if(!state.image||state.busy)throw new Error(t('图像尚未就绪'));changeROI(roi);},getState:()=>({language:getLanguage(),terrainAngle:state.terrainAngle,smoothing:+$('path-smoothing').value,pathMode:$('path-mode').value,showMask:$('show-mask').checked,showNodes:$('show-nodes').checked,inferredConnections:state.result?.bridges.length??0,busy:state.busy,ready:!!state.image,view:state.view,step:state.step,roi:state.roi,dirty:state.dirty,corrections:state.corrections,undo:state.undo.length,redo:state.redo.length})};
const lifecycle=new AbortController();if(document.modelContext?.registerTool){try{for(const tool of [{name:'read_ant_path_result',description:'Read the currently completed ant-path network in original image coordinates. Does not run extraction.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');const r=window.Formic.getResult();return r?{stats:r.stats,nodes:r.nodes,edges:r.edges,reviewRequired:true}:{status:'no_result'};}},{name:'extract_ant_paths',description:'Run classical segmentation and skeletonization using the image, selected region and parameters currently visible. Replaces previous extraction and manual edits.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');if(!state.image||state.busy)throw new Error('Image not ready or processing is already running');await extract();const r=window.Formic.getResult();return r?{stats:r.stats,reviewRequired:true}:{status:'cancelled_or_failed'};}}])Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{} }
$('continue-button').onclick=()=>setStep(state.step==='export'?'correct':'extract');
window.addEventListener('path-recognize:language',()=>{syncSliders();refreshLabels();$('toast').hidden=true;fitCanvas();});
initI18n();
window.addEventListener('pagehide',()=>{lifecycle.abort();state.worker?.terminate();});syncSliders();loadImage('./assets/sample.jpg','蚁穴示例.jpg',true);
